# Surah An-Nahl (chapter 16) — part 10: ayat 91-100 (IDs 1992-2001)
SURAH = 16

ENTRIES = {
1992: (
"اور اللہ کے عہد کو پورا کرو جب تم عہد کرو — اور قسموں کو ان کے پخت کرنے کے بعد مت توڑو — اور تم نے اللہ کو اپنا ضامن بنایا ہے — بے شک اللہ جانتا ہے جو تم کرتے ہو",
"""۱۔ اللہ کے ساتھ عہد کی عظمت؛ قسم توڑنے کی سزا؛ اللہ کو ضامن سمجھو؛ اپنے عمل کی جواب دہی۔
۲۔ ’’وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدتُّمْ وَلَا تَنقُضُوا الْأَيْمَانَ بَعْدَ تَوْكِيدِهَا وَقَدْ جَعَلْتُمُ اللَّهَ عَلَيْكُمْ كَفِيلًا إِنَّ اللَّهَ يَعْلَمُ مَا تَفْعَلُونَ‘‘ — اور اللہ کے عہد کو پورا کرو جب تم عہد کرو — اور قسموں کو ان کے پخت کرنے کے بعد مت توڑو — اور تم نے اللہ کو اپنا ضامن بنایا ہے — بے شک اللہ جانتا ہے جو تم کرتے ہو — یعنی اللہ کے ساتھ عہد کو پورا کرو جب تم عہد کرو — اور قسموں کو ان کے پخت ہونے کے بعد مت توڑو — اور تم نے اللہ کو اپنا ضامن بنایا ہے — بے شک اللہ جانتا ہے جو تم کرتے ہو۔
۳۔ عملی سبق: عہد پورا کرنا ایمان ہے؛ قسم کو ہلکی چیز نہ سمجھو؛ اللہ سب جانتا ہے۔"""
),
1993: (
"اور اس عورت کی طرح نہ بنو جس نے اپنا سوت مضبوط بنا کر ریزہ ریزہ کر دیا — تم اپنی قسموں کو آپس میں فریب بنانے کے لیے استعمال کرتے ہو — کہ ایک قوم دوسری سے بڑھ کر ہو — بس اللہ اسی سے تمہاری آزمائش کرتا ہے — اور قیامت کے دن وہ تمہارے سامنے واضح کر دے گا اس اختلاف کو جس میں تم پس و پیش کرتے تھے",
"""۱۔ قسم توڑنے والے بے بنیاد سوت کی مانند؛ اس سے قوم میں دھوکہ پھیلتا ہے؛ قیامت میں سب آشکار۔
۲۔ ’’وَلَا تَكُونُوا كَالَّتِي نَقَضَتْ غَزْلَهَا مِن بَعْدِ قُوَّۃٍ أَنكَاثًا تَتَّخِذُونَ أَيْمَانَكُمْ دَخَلًا بَيْنَكُمْ أَن تَكُونَ أُمَّۃٌ هِيَ أَرْبَىٰ مِنْ أُمَّۃٍ إِنَّمَا يَبْلُوكُمُ اللَّهُ بِهِ وَلَيُبَيِّنَنَّ لَكُمْ يَوْمَ الْقِيَامَۃِ مَا كُنتُمْ فِيهِ تَخْتَلِفُونَ‘‘ — اور اس عورت کی طرح نہ بنو جس نے اپنا سوت مضبوط بنا کر ریزہ ریزہ کر دیا — تم اپنی قسموں کو آپس میں فریب بنانے کے لیے استعمال کرتے ہو — کہ ایک قوم دوسری سے بڑھ کر ہو — بس اللہ اسی سے تمہاری آزمائش کرتا ہے — اور قیامت کے دن وہ تمہارے سامنے واضح کر دے گا اس اختلاف کو جس میں تم پس و پیش کرتے تھے — یعنی اس عورت کی طرح نہ بنو جس نے اپنا سوت مضبوط بنا کر ریزہ ریزہ کر دیا — تم اپنی قسموں کو آپس میں فریب بنانے کے لیے استعمال کرتے ہو کہ ایک قوم دوسری قوم سے بڑھ کر ہو — اللہ اسی سے تمہاری آزمائش کرتا ہے — اور قیامت کے دن وہ تمہارے سامنے واضح کر دے گا اس اختلاف کو جس میں تم پس و پیش کرتے تھے۔
۳۔ عملی سبق: اقوام کے درمیان دھوکہ کبھی جائز نہیں؛ اللہ سب کا حساب لے گا۔"""
),
1994: (
"اور اگر اللہ چاہتا تو تم سب کو ایک قوم بنا دیتا — لیکن وہ جس کو چاہتا ہے گمراہ کرتا ہے اور جس کو چاہتا ہے ہدایت دیتا ہے — اور تم سے یقیناً پوچھ گچھ ہوگی جو تم کرتے تھے",
"""۱۔ انسانوں میں اختلاف اللہ کی مشیت سے؛ ہدایت و گمراہی اللہ کے اختیار میں؛ ہر عمل کی جواب دہی۔
۲۔ ’’وَلَوْ شَاءَ اللَّهُ لَجَعَلَكُمْ أُمَّۃً وَاحِدَۃً وَلَٰكِن يُضِلُّ مَن يَشَاءُ وَيَهْدِي مَن يَشَاءُ وَلَتُسْأَلُنَّ عَمَّا كُنتُمْ تَعْمَلُونَ‘‘ — اور اگر اللہ چاہتا تو تم سب کو ایک قوم بنا دیتا — لیکن وہ جس کو چاہتا ہے گمراہ کرتا ہے اور جس کو چاہتا ہے ہدایت دیتا ہے — اور تم سے یقیناً پوچھ گچھ ہوگی جو تم کرتے تھے — یعنی اگر اللہ چاہتا تو تم سب کو ایک قوم بنا دیتا — لیکن وہ جس کو چاہتا ہے گمراہ کرتا ہے اور جس کو چاہتا ہے ہدایت دیتا ہے — اور تم سے یقیناً پوچھ گچھ ہوگی جو تم کرتے تھے۔
۳۔ عملی سبق: اختلاف اللہ کا امتحان ہے؛ ہر انسان اپنے عمل کا خود ذمہ دار ہے۔"""
),
1995: (
"اور اپنی قسموں کو آپس میں فریب نہ بناؤ — پس قدم جمنے کے بعد پھسل جائے — اور تم برائی کا مزہ چکھو اس کی بدولت کہ تم اللہ کے راستے سے روکتے ہو — اور تمہارے لیے عظیم عذاب ہے",
"""۱۔ قسم سے دھوکہ کرنے والا ہمیشہ خود نقصان اٹھائے گا؛ عذاب عظیم کا شکار ہوگا۔
۲۔ ’’وَلَا تَتَّخِذُوا أَيْمَانَكُمْ دَخَلًا بَيْنَكُمْ فَتَزِلَّ قَدَمٌ بَعْدَ ثُبُوتِهَا وَتَذُوقُوا السُّوءَ بِمَا صَدَدتُّمْ عَن سَبِيلِ اللَّهِ وَلَكُمْ عَذَابٌ عَظِيمٌ‘‘ — اور اپنی قسموں کو آپس میں فریب نہ بناؤ — پس قدم جمنے کے بعد پھسل جائے — اور تم برائی کا مزہ چکھو اس کی بدولت کہ تم اللہ کے راستے سے روکتے ہو — اور تمہارے لیے عظیم عذاب ہے — یعنی اپنی قسموں کو آپس میں فریب نہ بناؤ — پس قدم جمنے کے بعد پھسل جائے — اور تم برائی کا مزہ چکھو اس کی بدولت کہ تم اللہ کے راستے سے روکتے ہو — اور تمہارے لیے عظیم عذاب ہے۔
۳۔ عملی سبق: خیانت کا راستہ پھسلن ہے؛ اللہ کے راستے سے نہ روکو؛ عظیم عذاب سے بچو۔"""
),
1996: (
"اور اللہ کے عہد کو کسی چھوٹی قیمت پر مت بیچ دو — بے شک جو اللہ کے پاس ہے وہ تمہارے لیے بہتر ہے اگر تم جانتے ہو",
"""۱۔ دنیاوی فائدہ کے لیے اللہ کے عہد کو توڑنا گناہ ہے؛ اللہ کا اجر ہر چیز سے بہتر ہے۔
۲۔ ’’وَلَا تَشْتَرُوا بِعَهْدِ اللَّهِ ثَمَنًا قَلِيلًا إِنَّمَا عِندَ اللَّهِ هُوَ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ‘‘ — اور اللہ کے عہد کو کسی چھوٹی قیمت پر مت بیچ دو — بے شک جو اللہ کے پاس ہے وہ تمہارے لیے بہتر ہے اگر تم جانتے ہو — یعنی اللہ کے عہد کو کسی چھوٹی قیمت پر مت بیچ دو — بے شک جو اللہ کے پاس ہے وہ تمہارے لیے بہتر ہے اگر تم جانتے ہو۔
۳۔ عملی سبق: اللہ کا اجر سب سے عظیم ہے؛ دنیا کی تھوڑی سی چیز کے بدلے اس کو کبھی نہ بیچیں۔"""
),
1997: (
"جو تمہارے پاس ہے وہ ختم ہو جاتا ہے — اور جو اللہ کے پاس ہے وہ باقی ہے — اور ہم صبر کرنے والوں کو ان کے بہترین عمل کے مطابق اجر دیں گے",
"""۱۔ دنیا فانی ہے؛ اللہ کا گنج لامتناہی ہے؛ صبر کا بدلہ بہترین ہے۔
۲۔ ’’مَا عِندَكُمْ يَنفَدُ وَمَا عِندَ اللَّهِ بَاقٍ وَلَنَجْزِيَنَّ الَّذِينَ صَبَرُوا أَجْرَهُم بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ‘‘ — جو تمہارے پاس ہے وہ ختم ہو جاتا ہے — اور جو اللہ کے پاس ہے وہ باقی ہے — اور ہم صبر کرنے والوں کو ان کے بہترین عمل کے مطابق اجر دیں گے — یعنی تمہارے پاس جو ہے وہ ختم ہو جاتا ہے — اور جو اللہ کے پاس ہے وہ باقی ہے — اور ہم صبر کرنے والوں کو ان کے بہترین عمل کے مطابق اجر دیں گے۔
۳۔ عملی سبق: دنیا کی کوئی چیز باقی نہیں؛ آخرت میں اللہ کا اجر ہی اصل سرمایہ ہے۔"""
),
1998: (
"جو بھی نیک عمل کرے گا چاہے مرد ہو یا عورت — اور وہ مؤمن ہوگا — تو ہم اسے یقیناً ایک بہترین زندگی کے ساتھ زندہ کریں گے — اور ہم انہیں ان کے بہترین عمل کے مطابق اجر دیں گے",
"""۱۔ مرد و عورت دونوں کے نیک عمل کا اللہ کے ہاں ایک ہی اجر ہے؛ بہترین زندگی جنت ہے۔
۲۔ ’’مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُ حَيَاۃً طَيِّبَۃً وَلَنَجْزِيَنَّهُمْ أَجْرَهُم بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ‘‘ — جو بھی نیک عمل کرے گا چاہے مرد ہو یا عورت — اور وہ مؤمن ہوگا — تو ہم اسے یقیناً ایک بہترین زندگی کے ساتھ زندہ کریں گے — اور ہم انہیں ان کے بہترین عمل کے مطابق اجر دیں گے — یعنی جو بھی نیک عمل کرے گا چاہے مرد ہو یا عورت — اور وہ مؤمن ہوگا — تو ہم اسے ایک بہترین زندگی کے ساتھ زندہ کریں گے — اور ہم انہیں ان کے بہترین عمل کے مطابق اجر دیں گے۔
۳۔ عملی سبق: نیک عمل کرو خواہ مرد ہو یا عورت؛ اللہ دونوں کو بہترین بدلہ دے گا۔"""
),
1999: (
"پس جب تم قرآن پڑھو تو شیطان رجیم سے اللہ کی پناہ مانگو",
"""۱۔ قرآن تلاوت سے پہلے اعوذ باللہ پڑھنے کا حکم ہے؛ شیطان سے پناہ اللہ کی یاد دلاتی ہے۔
۲۔ ’’فَإِذَا قَرَأْتَ الْقُرْآنَ فَاسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ‘‘ — پس جب تم قرآن پڑھو تو شیطان رجیم سے اللہ کی پناہ مانگو — یعنی جب تم قرآن پڑھو تو شیطان رجیم سے اللہ کی پناہ مانگو۔
۳۔ عملی سبق: قرآن پڑھنے سے پہلے ہمیشہ اعوذ باللہ پڑھیں؛ یہ شیطان کو دور کرتا ہے۔"""
),
2000: (
"بے شک اس کا ان پر کوئی اثر نہیں جو ایمان لائے اور اپنے رب پر بھروسہ رکھتے ہیں",
"""۱۔ ایمان والوں اور اللہ پر بھروسہ کرنے والوں پر شیطان کا کوئی اثر نہیں۔
۲۔ ’’إِنَّهُ لَيْسَ لَهُ سُلْطَانٌ عَلَى الَّذِينَ آمَنُوا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ‘‘ — بے شک اس کا ان پر کوئی اثر نہیں جو ایمان لائے اور اپنے رب پر بھروسہ رکھتے ہیں — یعنی اس کا ان پر کوئی اثر نہیں جو ایمان لائے اور اپنے رب پر بھروسہ رکھتے ہیں۔
۳۔ عملی سبق: اللہ پر بھروسہ کرنے والا شیطان کے مکر سے محفوظ ہے۔"""
),
2001: (
"بلاشبہ اس کا اثر ان پر ہے جو اسے ولی بناتے ہیں اور جو اس کے ذریعے شرک کرتے ہیں",
"""۱۔ جو شیطان کو اپنا دوست بناتے ہیں اور اللہ کے ساتھ شرک کرتے ہیں ان پر اس کا اثر ہوتا ہے۔
۲۔ ’’إِنَّمَا سُلْطَانُهُ عَلَى الَّذِينَ يَتَوَلَّوْنَهُ وَالَّذِينَ هُم بِهِ مُشْرِكُونَ‘‘ — بلاشبہ اس کا اثر ان پر ہے جو اسے ولی بناتے ہیں اور جو اس کے ذریعے شرک کرتے ہیں — یعنی اس کا اثر ان پر ہے جو اسے ولی بناتے ہیں اور جو اس کے ذریعے شرک کرتے ہیں۔
۳۔ عملی سبق: شیطان کو دوست بنانے سے بچیں؛ شرک سے ہر قیمت پر پرہیز کریں۔"""
),
}
